import json, re
path = "/Users/mac/.cursor/projects/Users-mac-Desktop-CHcode/agent-transcripts/48dd9295-cbde-4984-aeb4-26a130b521d8/48dd9295-cbde-4984-aeb4-26a130b521d8.jsonl"
texts = []
for line in open(path):
    obj = json.loads(line)
    for part in obj.get('message',{}).get('content',[]):
        if part.get('type')=='tool_use':
            cmd = part.get('input',{}).get('command','')
            for m in re.finditer(r'TEXT = """(.*?)"""', cmd, re.DOTALL):
                texts.append(m.group(1))
for i,t in enumerate(texts):
    print(f'=== TEXT {i+1} ===')
    print(t)
    print()
